script:
# Run only for email-created tickets
if doc.via_email and doc.email_account == "ITSM":

    subject = (doc.subject or "").lower()

    # Set Urgency from subject
    if "critical" in subject:
        doc.priority = "Critical"
    elif "high" in subject:
        doc.priority = "High"
    elif "medium" in subject:
        doc.priority = "Medium"
    elif "low" in subject:
        doc.priority = "Low"

if doc.status == "In-Progress" and not doc.custom_assigned_to:
    frappe.throw("Please assign this ticket before moving to In-Progress.")

if doc.status == "Resolved":
    if not doc.custom_resolution_code:
        frappe.throw("Fill Resolution Code before resolving.")
    if not doc.custom_solution:
        frappe.throw("Fill Solution before resolving.")

if doc.status == "Closed":
    if not doc.custom_closure_code:
        frappe.throw("Fill Closure Code before closing.")
    if not doc.custom_closure_category:
        frappe.throw("Fill Closure Category before closing.")

if doc.status == "Cancelled" and not doc.custom_cancellation_remarks:
    frappe.throw("Fill Cancellation Remarks before cancelling.")

if doc.status == "Pending" and not doc.custom_pending_reason:
    frappe.throw("Fill Pending Reason before putting on hold.")

# No import statements allowed here
now = frappe.utils.now_datetime()

# 1. Logic for New Tickets (Automatic or Manual)
if doc.is_new():
    doc.custom_response_sla_breach = "NO"
    doc.custom_resolution_sla_breach = "NO"

# 2. Logic for existing or being-saved tickets
# Only check if the ticket is not yet finished
if doc.status not in ["Resolved", "Closed"]:

    # Check Response SLA Breach
    if doc.response_by and now > frappe.utils.get_datetime(doc.response_by):
        if doc.custom_response_sla_breach != "YES":
            doc.custom_response_sla_breach = "YES"

    # Check Resolution SLA Breach
    if doc.resolution_by and now > frappe.utils.get_datetime(doc.resolution_by):
        if doc.custom_resolution_sla_breach != "YES":
            doc.custom_resolution_sla_breach = "YES"

if doc.subject:
    # 1. Normalize subject for matching
    subject = doc.subject.lower()

    # 2. Map Subject to Urgency and Impact
    if "critical" in subject:
        doc.priority = "Critical"
        doc.custom_impact = "Severity 1"
    elif "high" in subject:
        doc.priority = "High"
        doc.custom_impact = "Severity 2"
    elif "medium" in subject:
        doc.priority = "Medium"
        doc.custom_impact = "Severity 3"
    elif "low" in subject:
        doc.priority = "Low"
        doc.custom_impact = "Severity 4"

    # 3. Calculate Priority (Logic matching your Client Script)
    priority_matrix = {
        "Critical": {"Severity 1": "P1", "Severity 2": "P1", "Severity 3": "P1", "Severity 4": "P2"},
        "High":     {"Severity 1": "P1", "Severity 2": "P2", "Severity 3": "P2", "Severity 4": "P3"},
        "Medium":   {"Severity 1": "P2", "Severity 2": "P3", "Severity 3": "P3", "Severity 4": "P4"},
        "Low":      {"Severity 1": "P3", "Severity 2": "P4", "Severity 3": "P4", "Severity 4": "P4"}
    }

    # Apply the priority based on the values set above
    if doc.priority in priority_matrix and doc.custom_impact in priority_matrix[doc.priority]:
        doc.custom_priorityy = priority_matrix[doc.priority][doc.custom_impact]

# Validation based on status

# When moving to Resolved
if doc.status == "Resolved":
    if not doc.custom_resolution_code or not doc.custom_solution:
        frappe.throw("You must fill Resolution Code and Solution before resolving.")

# When moving to Closed
if doc.status == "Closed":
    if not doc.custom_closure_code or not doc.custom_closure_category:
        frappe.throw("You must fill Closure Code and Closure Category before closing.")

# When moving to Cancelled
if doc.status == "Cancelled":
    if not doc.custom_cancellation_remarks:
        frappe.throw("You must fill Cancellation Remarks before cancelling the incident.")

# When moving to Pending
if doc.status == "Pending":
    if not doc.custom_pending_reason:
        frappe.throw("You must provide a Pending Reason before setting the status to Pending.")

if doc.email_account == "ERPNextsupport":
    if doc.status == "New":
        frappe.db.set_value("HD Ticket",doc.name,"status","Closed")

# ---------------------------------------------------------
# 1. AUTO CLOSE IF SUBJECT HAS "ALERT"
# ---------------------------------------------------------
subject_text = (doc.subject or "").lower()

if "alert" in subject_text:
    # only auto-close if not already closed/cancelled
    if doc.workflow_state not in ["Closed", "Cancelled"]:

        # mark bypass so validations & workflow do not block
        doc.flags.ignore_workflow = True

        # fill mandatory fields
        doc.custom_resolution_code = "Resolved"
        doc.custom_solution = "System auto-closure: 'alert' keyword found."

        doc.custom_closure_code = "Closed"
        doc.custom_closure_category = "Prod Issue"

        # move through final state
        doc.workflow_state = "Closed"
        doc.status = "Closed"
        doc.docstatus = 1   # submit


# ---------------------------------------------------------
# 2. STRICT VALIDATIONS FOR MANUAL USERS
# ---------------------------------------------------------
if not doc.flags.ignore_workflow:

    if doc.status == "Resolved":
        if not doc.custom_resolution_code or not doc.custom_solution:
            frappe.throw(
                "You must fill Resolution Code and Solution before resolving."
            )

    if doc.status == "Closed":
        if not doc.custom_closure_code or not doc.custom_closure_category:
            frappe.throw(
                "You must fill Closure Code and Closure Category before closing."
            )

    if doc.status == "Cancelled":
        if not doc.custom_cancellation_remarks:
            frappe.throw(
                "You must fill Cancellation Remarks before cancelling."
            )

    if doc.status == "Pending":
        if not doc.custom_pending_reason:
            frappe.throw(
                "You must provide Pending Reason before setting to Pending."
            )

# Auto move ticket to In-Progress when assigned

if doc.status == "New":

    assignment_exists = frappe.db.exists(
        "ToDo",
        {
            "reference_type": "HD Ticket",
            "reference_name": doc.name,
            "status": "Open"
        }
    )

    if assignment_exists:
        doc.status = "In-Progress"

# Ensure old doc exists
old_doc = doc.get_doc_before_save()

if old_doc:
    # Check status change
    if old_doc.status != doc.status:

        # Debug (you can remove later)
        frappe.msgprint(f"Old: {old_doc.status} | New: {doc.status}")

        if old_doc.status == "New" and doc.status == "In Progress":

            # Set only if not already set
            if not doc.first_responded_on:
                doc.first_responded_on = frappe.utils.now_datetime()
